const HINWEIS_SCHLUESSEL = { "gilt für beide": "hnw_0", "eigener Schalter, optional": "hnw_1", "Shelly, Relais oder Eingang": "hnw_2", "eigene Entität, Watt": "hnw_3", "Soll Vorlauf": "hnw_4", "Shelly oder eigener Schalter": "hnw_5", "Switch zum Ein/Ausschalten der Zirkulation": "hnw_6", "SetHeatpump oder TOP0": "hnw_7", "Quelle in der Integration unter COP Quelle wählbar": "hnw_8", "nur ohne Leistungswerte der Wärmepumpe genutzt": "hnw_13", "stündliche Vorhersage; leer: wie HeishaMon by Lutarym, sonst automatisch": "hnw_14", "eigene Entität, °C": "hnw_9", "eigener Schalter oder Sensor": "hnw_10", "eigene Entität, °C; Kamin allein: TOP47": "hnw_11", "eigener Schalter oder Sensor; Kamin allein: OPT5": "hnw_12" };

/** Setzt Werte in Platzhalter wie {n} ein. */
export function tf(text, werte) {
  return String(text).replace(/\{(\w+)\}/g, (_, k) =>
    werte && werte[k] !== undefined ? werte[k] : `{${k}}`
  );
}

/** Zuordnung deutscher Auswahl- und Zustandswerte zu Sprachschluesseln. */
const WERT_SCHLUESSEL = { "Wärmepumpe": "w_20", "Pumpe HK1": "w_21", "Pumpe HK2": "w_22", "Heizstab läuft": "w_43", "Pumpe Kamin": "w_44", "Pumpe Solarthermie": "w_45", "Pumpe HK3": "w_46", "Pumpe HK4": "w_47", "HK3 Wasser": "w_48", "HK4 Wasser": "w_49", "Kamin": "kamin", "Solarthermie": "solarthermie", "Abtauung": "w_25", "Zirkulation Status": "w_26", "Aufheizen": "w_27", "Legionellenschutz": "w_28", "PV Leistung": "w_29", "Außen": "w_30", "Vorlauf": "w_31", "Rücklauf": "w_32", "Puffer": "w_33", "HK1 Wasser": "w_34", "HK2 Wasser": "w_35", "Verdichter": "w_36", "Durchfluss": "w_37", "Panasonic Aquarea, HeishaMon über MQTT-Namensschema": "w_38", "Nur Heizen": "w_0", "Nur Kühlen": "w_1", "Automatik Heizen": "w_2", "Nur Warmwasser": "w_3", "Heizen und Warmwasser": "w_4", "Kühlen und Warmwasser": "w_5", "Automatik Heizen und Warmwasser": "w_6", "Automatik Kühlen": "w_7", "Automatik Kühlen und Warmwasser": "w_8", "Aus": "w_9", "Stufe 1": "w_10", "Stufe 2": "w_11", "Stufe 3": "w_12", "30 Minuten": "w_13", "60 Minuten": "w_14", "90 Minuten": "w_15", "Heizung": "w_16", "Warmwasser": "w_17", "läuft": "w_18", "aus": "w_19" };

/** Auswahl- oder Zustandswert in der gewuenschten Sprache. */
export function wertText(wert, sprache) {
  const k = WERT_SCHLUESSEL[wert];
  return k ? t(k, sprache) : wert;
}

/** Beschriftung eines Entitaetsfeldes in der gewuenschten Sprache. */
export function feldText(feld, sprache) {
  return TEXTE[`fld_${feld.key}`] ? t(`fld_${feld.key}`, sprache) : feld.label;
}

/** Gruppenname in der gewuenschten Sprache. */
export function gruppenText(name, sprache) {
  const k = GRUPPEN_SCHLUESSEL[name];
  return k ? t(k, sprache) : name;
}

/** Hinweis zu einem Feld. Deutsche Teile werden uebersetzt, technische
 *  Angaben wie TOP-Nummern oder Befehlsnamen bleiben stehen. */
export function hinweisText(hint, sprache) {
  let s = String(hint || "");
  Object.keys(HINWEIS_SCHLUESSEL)
    .sort((x, y) => y.length - x.length)
    .forEach((de) => {
      if (s.includes(de)) s = s.split(de).join(t(HINWEIS_SCHLUESSEL[de], sprache));
    });
  return s;
}

/** Liefert einen Text in der gewuenschten Sprache. */
export function t(schluessel, sprache) {
  const paket = EIGENE_SPRACHEN[sprache];
  if (paket && typeof paket.texte[schluessel] === "string" && paket.texte[schluessel]) {
    return paket.texte[schluessel];
  }
  const eintrag = TEXTE[schluessel];
  if (!eintrag) return schluessel;
  const basis = paket && paket.basis;
  return eintrag[sprache] || (basis && eintrag[basis]) || eintrag.en || eintrag.de;
}
